# Liquid filter: {{ post.image | thumbnail }}
#
# Returns the small WebP copy generated by scripts/make_thumbnails.py when that file
# exists, and the original image path otherwise:
#   img/posts/x.jpg                  -> /img/thumbs/posts/x.webp
#   assets/images/linkedin/<post>/<f> -> /img/thumbs/linkedin/<post>/<f>.webp
module Jekyll
  module ThumbnailFilter
    def thumbnail(path)
      return path unless path.is_a?(String)

      relative = path.sub(%r{\A(\.\./|/)+}, '')
      if relative.start_with?('assets/images/linkedin/')
        # LinkedIn post images have no extension: assets/images/linkedin/<post>/<file> -> img/thumbs/linkedin/<post>/<file>.webp
        thumb = File.join('img', 'thumbs', 'linkedin', relative.sub(%r{\Aassets/images/linkedin/}, '')) + '.webp'
      elsif relative.start_with?('img/')
        thumb = File.join('img', 'thumbs', relative.sub(%r{\Aimg/}, '')).sub(/\.[^.\/]+\z/, '.webp')
      else
        return path
      end
      source = @context.registers[:site].source
      File.exist?(File.join(source, thumb)) ? "/#{thumb}" : path
    end
  end
end

Liquid::Template.register_filter(Jekyll::ThumbnailFilter)
